#include <set>
#include <iostream>

int main() {
    std::set<int> s = {10, 20};
    auto it = s.find(10);

    // *it = 15; // ERROR: assignment of read-only location

    if (it != s.end()) {
        int old_val = *it;
        // Correct modification procedure:
        it = s.erase(it); // Erase old element (O(log N))
        s.insert(15);     // Insert new element (O(log N))
        std::cout << "Modified: 10 -> 15. Set size: " << s.size() << std::endl;
    }
}
